// OFFLINE STAND-IN for a vector search.
// Real RAG embeds the question and every proposal chunk, then ranks by cosine
// similarity. Here we rank by plain keyword overlap so the demo runs with NO
// embedding model — the SHAPE (retrieve top-k, then ground the LLM on them) is
// identical. Swap this node for a Vector Store (retrieve) node to go semantic.

const input = $input.first().json;
const question = input.question;
const proposals = input.proposals;

const stop = new Set(['the','and','for','our','past','with','that','this','their','please','help','analyse','analyze','which','what','carry','worth','against','compare','comparing','their']);
const qTerms = (question.toLowerCase().match(/[a-z]+/g) || [])
  .filter(t => t.length > 3 && !stop.has(t));

const scored = proposals.map(p => {
  const hay = `${p.title} ${p.text} ${p.country} ${p.sector}`.toLowerCase();
  let score = 0;
  for (const t of qTerms) { if (hay.includes(t)) score++; }
  return { ...p, _score: score };
});

scored.sort((a, b) => b._score - a._score);

const TOP_K = 5; // a cross-proposal comparison wants the whole corpus; a narrow
                 // question ("the Kenya solar proposal") would use TOP_K = 1-2.
const top = scored.slice(0, TOP_K);

const context = top
  .map(p => `### ${p.proposal_id} — ${p.title} (${p.country}, ${p.year})\n${p.text}`)
  .join('\n\n');

return [{ json: {
  question,
  retrieved: top.map(p => ({ proposal_id: p.proposal_id, country: p.country, score: p._score })),
  context
} }];
